#include <Arduino.h>
#include <ETH.h>
#include <WebServer.h>
#include <HTTPUpdateServer.h>
#include <WiFiClient.h>
#include <WiFiServer.h>
#include <time.h>
#include <vector>

#ifndef SUNBRIDGE_VERSION
#define SUNBRIDGE_VERSION "dev"
#endif

static const IPAddress LOCAL_IP(192,168,10,27), GATEWAY(192,168,10,1), SUBNET(255,255,255,0), DNS1(192,168,10,1), SDONGLE_IP(192,168,10,2);
static constexpr uint16_t SDONGLE_PORT=502, SUNBRIDGE_PORT=5502; static constexpr uint8_t DEVICE_ID=1;
static constexpr int ETH_PHY_ADDR=1, ETH_PHY_POWER=16, ETH_MDC_PIN=23, ETH_MDIO_PIN=18;
static constexpr eth_clock_mode_t ETH_CLK_MODE=ETH_CLOCK_GPIO0_IN; static constexpr eth_phy_type_t ETH_PHY_TYPE=ETH_PHY_LAN8720;
static constexpr uint32_t POLL_INTERVAL_MS=10000, CONNECT_WAIT_MS=2000, BATCH_DELAY_MS=500, UPSTREAM_TIMEOUT_MS=5000;
static constexpr size_t MAX_CLIENTS=4, MAX_HISTORY=10;
struct RegisterBatch{uint16_t start,count;};
static const RegisterBatch REGISTER_BATCHES[]={{30000,15},{30015,50},{30071,1},{30075,2},{32000,20},{32064,52},{37100,38},{37200,2},{37760,28},{40126,2},{42900,10},{43006,2},{47000,1},{47089,1}};
static constexpr size_t BATCH_COUNT=sizeof(REGISTER_BATCHES)/sizeof(REGISTER_BATCHES[0]);
static constexpr uint16_t SETUP_PASSTHROUGH_START=30000, SETUP_PASSTHROUGH_END=30071;
struct CacheEntry{uint16_t reg,value;}; std::vector<CacheEntry> cacheEntries; SemaphoreHandle_t cacheMutex,upstreamMutex;
struct ClientSlot{WiFiClient client;bool used=false;IPAddress ip;uint16_t port=0;time_t connectedAt=0;uint32_t connectedMillis=0;time_t lastRequestAt=0;uint32_t requestCount=0;std::vector<uint8_t> rx;}; ClientSlot clients[MAX_CLIENTS];
struct ClientHistory{String ip;uint16_t port=0;time_t connectedAt=0,disconnectedAt=0;uint32_t requestCount=0;}; ClientHistory history[MAX_HISTORY]; size_t historyCount=0,historyHead=0;
WiFiServer modbusServer(SUNBRIDGE_PORT); WebServer webServer(80); HTTPUpdateServer httpUpdater; volatile bool ethConnected=false; volatile uint32_t lastSuccessfulPollMillis=0,pollOkBatches=0,upstreamErrors=0;
static String formatTime(time_t t){if(t<1700000000)return "NTP non sincronizzato";struct tm x;localtime_r(&t,&x);char b[32];strftime(b,sizeof(b),"%d/%m/%Y %H:%M:%S",&x);return String(b);}
static String formatDuration(uint32_t s){uint32_t d=s/86400;s%=86400;uint32_t h=s/3600;s%=3600;uint32_t m=s/60;s%=60;char b[40];if(d)snprintf(b,sizeof(b),"%lud %02lu:%02lu:%02lu",(unsigned long)d,(unsigned long)h,(unsigned long)m,(unsigned long)s);else snprintf(b,sizeof(b),"%02lu:%02lu:%02lu",(unsigned long)h,(unsigned long)m,(unsigned long)s);return String(b);}
static void initCache(){for(auto &b:REGISTER_BATCHES)for(uint16_t i=0;i<b.count;i++)cacheEntries.push_back({(uint16_t)(b.start+i),0});}
static bool cacheGetRange(uint16_t start,uint16_t count,std::vector<uint16_t>&v){v.clear();if(xSemaphoreTake(cacheMutex,pdMS_TO_TICKS(1000))!=pdTRUE)return false;for(uint16_t i=0;i<count;i++){bool f=false;for(auto&e:cacheEntries)if(e.reg==start+i){v.push_back(e.value);f=true;break;}if(!f){xSemaphoreGive(cacheMutex);v.clear();return false;}}xSemaphoreGive(cacheMutex);return true;}
static void cacheSetRange(uint16_t start,const std::vector<uint16_t>&v){if(xSemaphoreTake(cacheMutex,pdMS_TO_TICKS(1000))!=pdTRUE)return;for(size_t i=0;i<v.size();i++)for(auto&e:cacheEntries)if(e.reg==start+i){e.value=v[i];break;}xSemaphoreGive(cacheMutex);}
static bool readExact(WiFiClient&c,uint8_t*b,size_t n,uint32_t timeout){size_t g=0;uint32_t st=millis();while(g<n&&c.connected()){while(c.available()&&g<n){int r=c.read(b+g,n-g);if(r>0)g+=r;}if(g>=n)return true;if(millis()-st>timeout)return false;vTaskDelay(pdMS_TO_TICKS(2));}return g==n;}
static bool readResponse(WiFiClient&c,uint16_t&tx,uint8_t&uid,std::vector<uint8_t>&p){uint8_t h[7];if(!readExact(c,h,7,UPSTREAM_TIMEOUT_MS))return false;tx=(h[0]<<8)|h[1];uint16_t proto=(h[2]<<8)|h[3],len=(h[4]<<8)|h[5];uid=h[6];if(proto||len<2||len>260)return false;p.resize(len-1);return readExact(c,p.data(),p.size(),UPSTREAM_TIMEOUT_MS);}
static bool openUpstream(WiFiClient&c){c.setTimeout(UPSTREAM_TIMEOUT_MS);if(!c.connect(SDONGLE_IP,SDONGLE_PORT,10000))return false;vTaskDelay(pdMS_TO_TICKS(CONNECT_WAIT_MS));return true;}
static bool readOnConnection(WiFiClient&c,uint8_t uid,uint16_t start,uint16_t count,std::vector<uint16_t>&v){uint8_t q[12]={0,0,0,0,0,6,uid,3,(uint8_t)(start>>8),(uint8_t)start,(uint8_t)(count>>8),(uint8_t)count};if(c.write(q,12)!=12)return false;uint16_t tx;uint8_t ru;std::vector<uint8_t>p;if(!readResponse(c,tx,ru,p)||p.size()<2||p[0]!=3||p[0]>=0x80||p[1]<count*2||p.size()<2+p[1])return false;v.resize(count);for(uint16_t i=0;i<count;i++)v[i]=(p[2+i*2]<<8)|p[3+i*2];return true;}
static bool directRead(uint8_t uid,uint16_t start,uint16_t count,std::vector<uint16_t>&v){if(xSemaphoreTake(upstreamMutex,pdMS_TO_TICKS(15000))!=pdTRUE)return false;WiFiClient c;bool ok=openUpstream(c)&&readOnConnection(c,uid,start,count,v);c.stop();xSemaphoreGive(upstreamMutex);if(!ok)upstreamErrors++;return ok;}
static bool forwardWrite(uint8_t uid,uint16_t reg,uint16_t val){if(xSemaphoreTake(upstreamMutex,pdMS_TO_TICKS(15000))!=pdTRUE)return false;WiFiClient c;bool ok=false;if(openUpstream(c)){uint8_t q[12]={0,0,0,0,0,6,uid,6,(uint8_t)(reg>>8),(uint8_t)reg,(uint8_t)(val>>8),(uint8_t)val};if(c.write(q,12)==12){uint16_t tx;uint8_t ru;std::vector<uint8_t>p;ok=readResponse(c,tx,ru,p)&&p.size()>=5&&p[0]==6;}}c.stop();xSemaphoreGive(upstreamMutex);if(!ok)upstreamErrors++;return ok;}
static std::vector<uint8_t> response(uint16_t tx,uint8_t uid,const std::vector<uint8_t>&p){std::vector<uint8_t>o(7+p.size());uint16_t l=p.size()+1;o[0]=tx>>8;o[1]=tx;o[2]=o[3]=0;o[4]=l>>8;o[5]=l;o[6]=uid;memcpy(o.data()+7,p.data(),p.size());return o;}
static void recordDisconnect(const ClientSlot&s){history[historyHead]={s.ip.toString(),s.port,s.connectedAt,time(nullptr),s.requestCount};historyHead=(historyHead+1)%MAX_HISTORY;if(historyCount<MAX_HISTORY)historyCount++;}
static void closeClient(size_t i){if(!clients[i].used)return;recordDisconnect(clients[i]);clients[i].client.stop();clients[i].used=false;clients[i].rx.clear();}
static void acceptClients(){if(!modbusServer.hasClient())return;WiFiClient in=modbusServer.available();if(!in)return;for(size_t i=0;i<MAX_CLIENTS;i++)if(!clients[i].used){clients[i].client=in;clients[i].used=true;clients[i].ip=in.remoteIP();clients[i].port=in.remotePort();clients[i].connectedAt=time(nullptr);clients[i].connectedMillis=millis();clients[i].lastRequestAt=0;clients[i].requestCount=0;clients[i].rx.clear();clients[i].rx.reserve(300);Serial.printf("Client connected: %s:%u\n",clients[i].ip.toString().c_str(),clients[i].port);return;}in.stop();}
static void processFrame(ClientSlot&s,const uint8_t*f,size_t n){if(n<8)return;uint16_t tx=(f[0]<<8)|f[1],proto=(f[2]<<8)|f[3],len=(f[4]<<8)|f[5];uint8_t uid=f[6];if(proto||len<2||n!=6+len)return;const uint8_t*p=f+7;size_t pn=len-1;uint8_t fc=p[0];std::vector<uint8_t>rp;s.requestCount++;s.lastRequestAt=time(nullptr);if(fc==3&&pn>=5){uint16_t reg=(p[1]<<8)|p[2],count=(p[3]<<8)|p[4];std::vector<uint16_t>v;bool ok=cacheGetRange(reg,count,v);if(!ok&&reg>=SETUP_PASSTHROUGH_START&&reg<=SETUP_PASSTHROUGH_END)ok=directRead(uid,reg,count,v);if(!ok)rp={(uint8_t)0x83,2};else{rp.resize(2+count*2);rp[0]=3;rp[1]=count*2;for(uint16_t i=0;i<count;i++){rp[2+i*2]=v[i]>>8;rp[3+i*2]=v[i];}}}else if(fc==6&&pn>=5){uint16_t reg=(p[1]<<8)|p[2],val=(p[3]<<8)|p[4];if(forwardWrite(uid,reg,val))rp.assign(p,p+5);else rp={(uint8_t)0x86,4};}else rp={(uint8_t)(fc|0x80),1};auto o=response(tx,uid,rp);s.client.write(o.data(),o.size());}
static void serviceClients(){for(size_t i=0;i<MAX_CLIENTS;i++){auto&s=clients[i];if(!s.used)continue;if(!s.client.connected()){closeClient(i);continue;}while(s.client.available()){int b=s.client.read();if(b<0)break;s.rx.push_back((uint8_t)b);if(s.rx.size()>1024){closeClient(i);break;}}while(s.used&&s.rx.size()>=7){uint16_t l=(s.rx[4]<<8)|s.rx[5];if(l<2||l>260){closeClient(i);break;}size_t total=6+l;if(s.rx.size()<total)break;processFrame(s,s.rx.data(),total);s.rx.erase(s.rx.begin(),s.rx.begin()+total);}}}
static void pollTask(void*){for(;;){if(!ethConnected){vTaskDelay(pdMS_TO_TICKS(1000));continue;}if(xSemaphoreTake(upstreamMutex,pdMS_TO_TICKS(15000))!=pdTRUE){vTaskDelay(pdMS_TO_TICKS(1000));continue;}WiFiClient c;uint32_t ok=0;if(openUpstream(c)){for(auto&b:REGISTER_BATCHES){std::vector<uint16_t>v;if(readOnConnection(c,DEVICE_ID,b.start,b.count,v)){cacheSetRange(b.start,v);ok++;}else upstreamErrors++;vTaskDelay(pdMS_TO_TICKS(BATCH_DELAY_MS));}}else upstreamErrors++;c.stop();xSemaphoreGive(upstreamMutex);pollOkBatches=ok;if(ok)lastSuccessfulPollMillis=millis();Serial.printf("Poll: %lu/%u batches OK\n",(unsigned long)ok,(unsigned)BATCH_COUNT);vTaskDelay(pdMS_TO_TICKS(POLL_INTERVAL_MS));}}
static String htmlPage(){String h;h.reserve(11000);h=F("<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta http-equiv='refresh' content='5'><title>Huawei SunBridge ESP32</title><style>body{font-family:system-ui;background:#111827;color:#e5e7eb;margin:0;padding:20px}.wrap{max-width:1100px;margin:auto}.card{background:#1f2937;border-radius:12px;padding:18px;margin:14px 0}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #374151;text-align:left}.ok{color:#34d399}.bad{color:#f87171}.muted{color:#9ca3af}code,a{color:#93c5fd}</style></head><body><div class='wrap'>");h+="<h1>Huawei SunBridge ESP32</h1><div class='muted'>Firmware "+String(SUNBRIDGE_VERSION)+" · WT32-ETH01 v1.4</div><div class='card'><h2>Ethernet</h2><table><tr><td>Status</td><td class='"+String(ethConnected?"ok'>UP":"bad'>DOWN")+"</td></tr><tr><td>IP</td><td><code>"+ETH.localIP().toString()+"</code></td></tr><tr><td>Gateway</td><td>"+ETH.gatewayIP().toString()+"</td></tr><tr><td>Link</td><td>"+String(ETH.linkSpeed())+" Mbps "+String(ETH.fullDuplex()?"Full Duplex":"Half Duplex")+"</td></tr></table></div>";h+="<div class='card'><h2>SDongle / proxy</h2><table><tr><td>SDongle</td><td><code>"+SDONGLE_IP.toString()+":502</code></td></tr><tr><td>SunBridge</td><td><code>"+LOCAL_IP.toString()+":5502</code></td></tr><tr><td>Ultimo poll</td><td>"+String(pollOkBatches)+"/"+String(BATCH_COUNT)+" batch OK</td></tr><tr><td>Età cache</td><td>"+(lastSuccessfulPollMillis?String((millis()-lastSuccessfulPollMillis)/1000)+" s":String("mai aggiornata"))+"</td></tr><tr><td>Errori upstream</td><td>"+String(upstreamErrors)+"</td></tr><tr><td>Uptime</td><td>"+formatDuration(millis()/1000)+"</td></tr></table></div>";h+=F("<div class='card'><h2>Client Modbus connessi</h2><table><tr><th>IP</th><th>Porta</th><th>Connesso dal</th><th>Durata</th><th>Ultima richiesta</th><th>Richieste</th></tr>");size_t active=0;for(size_t i=0;i<MAX_CLIENTS;i++)if(clients[i].used){active++;h+="<tr><td><code>"+clients[i].ip.toString()+"</code></td><td>"+String(clients[i].port)+"</td><td>"+formatTime(clients[i].connectedAt)+"</td><td>"+formatDuration((millis()-clients[i].connectedMillis)/1000)+"</td><td>"+(clients[i].lastRequestAt?formatTime(clients[i].lastRequestAt):String("—"))+"</td><td>"+String(clients[i].requestCount)+"</td></tr>";}if(!active)h+=F("<tr><td colspan='6' class='muted'>Nessun client connesso</td></tr>");h+="</table><p><b>Client attivi:</b> "+String(active)+" / "+String(MAX_CLIENTS)+"</p></div>";h+=F("<div class='card'><h2>Ultime disconnessioni</h2><table><tr><th>IP</th><th>Porta</th><th>Connessione</th><th>Disconnessione</th><th>Richieste</th></tr>");if(!historyCount)h+=F("<tr><td colspan='5' class='muted'>Nessuna disconnessione registrata</td></tr>");for(size_t n=0;n<historyCount;n++){size_t i=(historyHead+MAX_HISTORY-1-n)%MAX_HISTORY;auto&x=history[i];h+="<tr><td><code>"+x.ip+"</code></td><td>"+String(x.port)+"</td><td>"+formatTime(x.connectedAt)+"</td><td>"+formatTime(x.disconnectedAt)+"</td><td>"+String(x.requestCount)+"</td></tr>";}h+="</table></div><div class='card'><h2>Aggiornamento firmware OTA</h2><p>Carica il normale <code>firmware.bin</code> via Ethernet, senza USB-TTL.</p><p><a href='/update'>Apri pagina aggiornamento OTA</a></p></div><div class='muted'>Ora locale: "+formatTime(time(nullptr))+" · aggiornamento ogni 5 s</div></div></body></html>";return h;}
static void setupWeb(){webServer.on("/",HTTP_GET,[](){webServer.send(200,"text/html; charset=utf-8",htmlPage());});webServer.on("/health",HTTP_GET,[](){String j=String("{\"ethernet\":")+(ethConnected?"true":"false")+",\"poll_ok\":"+String(pollOkBatches)+",\"poll_total\":"+String(BATCH_COUNT)+",\"upstream_errors\":"+String(upstreamErrors)+"}";webServer.send(200,"application/json",j);});httpUpdater.setup(&webServer,"/update");webServer.begin();}
void WiFiEvent(WiFiEvent_t e){switch(e){case ARDUINO_EVENT_ETH_START:ETH.setHostname("huawei-sunbridge");break;case ARDUINO_EVENT_ETH_GOT_IP:ethConnected=true;Serial.printf("Ethernet UP: %s\n",ETH.localIP().toString().c_str());break;case ARDUINO_EVENT_ETH_DISCONNECTED:case ARDUINO_EVENT_ETH_STOP:ethConnected=false;break;default:break;}}
void setup(){Serial.begin(115200);delay(300);cacheMutex=xSemaphoreCreateMutex();upstreamMutex=xSemaphoreCreateMutex();initCache();WiFi.onEvent(WiFiEvent);ETH.begin(ETH_PHY_TYPE,ETH_PHY_ADDR,ETH_MDC_PIN,ETH_MDIO_PIN,ETH_PHY_POWER,ETH_CLK_MODE);ETH.config(LOCAL_IP,GATEWAY,SUBNET,DNS1);uint32_t st=millis();while(!ethConnected&&millis()-st<15000)delay(100);configTzTime("CET-1CEST,M3.5.0,M10.5.0/3","pool.ntp.org","time.google.com","time.cloudflare.com");modbusServer.begin();modbusServer.setNoDelay(true);setupWeb();xTaskCreatePinnedToCore(pollTask,"sdongle-poll",8192,nullptr,1,nullptr,0);Serial.printf("SunBridge %s:%u -> SDongle %s:%u\n",LOCAL_IP.toString().c_str(),SUNBRIDGE_PORT,SDONGLE_IP.toString().c_str(),SDONGLE_PORT);}
void loop(){acceptClients();serviceClients();webServer.handleClient();delay(1);}
